    dlg.innerHTML = '<div class="box"><h3>Journal style</h3><p class="msg">Current: <b>' + esc6(current ? current.name : "none chosen") + "</b> \xB7 references: " + esc6(citeStyleLabel(view.state.doc, st2.cite)) + '</p><input type="search" class="jq" placeholder="Journal name, e.g. Nano Letters, 2D Materials, Physical Review B" spellcheck="false"><div class="jlist" role="listbox"></div><h4>Other journals: reference style only</h4><p class="msg small">From the citation style repository Zotero uses (about 10 000 journals). Heading and figure formats stay as they are.</p><div class="jcsl"><span class="muted">Type a journal name above.</span></div><p class="msg small">The settings are starting points from the journals\u2019 author guidelines. Check the journal\u2019s current guide before you submit.</p><div class="buttons"><button data-act="file">Load a .csl file\u2026</button><span class="grow"></span><button data-act="close" class="primary">Close</button></div></div>';
    const q2 = dlg.querySelector(".jq"), list3 = dlg.querySelector(".jlist"), csl = dlg.querySelector(".jcsl");
