      if (my2 !== seq3) return;
      if (!r2 || r2.error) {
        csl.innerHTML = '<span class="err">' + esc6(r2 ? r2.error : "No answer.") + "</span>";
        return;
      }
      csl.innerHTML = r2.items.length ? r2.items.slice(0, 12).map((x3) => '<button class="jitem" data-csl="' + esc6(x3.name) + '">' + esc6(x3.title) + ' <small class="muted">' + esc6(x3.format) + "</small></button>").join("") + (r2.total > 12 ? '<small class="muted">' + (r2.total - 12) + " more \u2014 type more of the name.</small>" : "") : '<span class="muted">No style found for \u201C' + esc6(text2) + "\u201D.</span>";
